insert into public.awareness_posts (slug, title_en, title_bn, body_en, body_bn, category_id, published) values
  ('aw-1', 'Don’t burn waste — it poisons the air your family breathes', 'ময়লা পোড়াবেন না — এই ধোঁয়া আপনার পরিবারের ফুসফুসে যায়', 'Burning plastic releases dioxins linked to asthma and cancer. Bag your waste and hand it to the city collector instead.', 'প্লাস্টিক পোড়ালে ডাইঅক্সিন নির্গত হয়, যা হাঁপানি ও ক্যানসারের কারণ। ময়লা ব্যাগে ভরে সিটি কর্পোরেশনের সংগ্রাহককে দিন।', 'air_pollution', true),
  ('aw-2', 'One plastic bag in the drain can flood your street', 'ড্রেনে একটি পলিথিন আপনার রাস্তা ডুবিয়ে দিতে পারে', 'Most waterlogging in our cities starts with blocked drains. Keep plastic out of drains and canals.', 'শহরের বেশিরভাগ জলাবদ্ধতার শুরু বন্ধ ড্রেন থেকে। ড্রেন ও খালে পলিথিন ফেলবেন না।', 'drain_blocked', true),
  ('aw-3', 'Footpaths are for people', 'ফুটপাত মানুষের হাঁটার জন্য', 'When footpaths are blocked, children, elders and wheelchair users are pushed into traffic.', 'ফুটপাত দখল হলে শিশু, বয়স্ক ও হুইলচেয়ার ব্যবহারকারীরা ঝুঁকি নিয়ে রাস্তায় নামতে বাধ্য হন।', 'footpath', true),
  ('aw-4', 'Saw an open manhole? Mark it, then report it', 'খোলা ম্যানহোল দেখলে চিহ্ন দিন, তারপর রিপোর্ট করুন', 'Put a branch or brick around it so others notice, then post a report so it gets covered.', 'অন্যরা যেন দেখতে পায় তাই পাশে ডাল বা ইট রাখুন, তারপর রিপোর্ট করুন।', 'open_manhole', true),
  ('aw-5', 'Horns don’t move traffic', 'হর্ন বাজালে যানজট কমে না', 'Noise above 70 dB harms hearing and heart health. Silence zones near hospitals and schools are the law.', '৭০ ডেসিবেলের বেশি শব্দ শ্রবণশক্তি ও হৃদ্‌যন্ত্রের ক্ষতি করে। হাসপাতাল ও স্কুলের আশপাশ নীরব এলাকা।', 'noise', true)
